sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var url_h = "";
    var sys_id = api.data.record.sysId;
    var url_l = '&sysparm_view=';
    var select = api.state.url;

    if(select == "default"){
        url_h = "/x_1882833_organi_0_meisai_list.do?XLSX&sysparm_query=kenmu_number=主務&sinsei_number.sys_id=";
    }else{
        url_h = "/x_1882833_organi_0_meisai_list.do?XLSX&sysparm_query=kenmu_number!=新規入力欄^kenmu_number!=入力中&sinsei_number.sys_id=";
    }

    var url = url_h + sys_id + url_l + select;

    api.setState('url',url);

}
